const PR23=[{label:"Ví dụ: Xâu con chung dài nhất",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    string a = \"ABCBDAB\", b = \"BDCABA\";\n    int n = a.size(), m = b.size();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;\n            else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}]},{label:"Ví dụ: Khoảng cách sửa",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    string a = \"SUNDAY\", b = \"SATURDAY\";\n    int n = a.size(), m = b.size();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    for (int i = 0; i <= n; i++) dp[i][0] = i;   // xóa hết i ký tự\n    for (int j = 0; j <= m; j++) dp[0][j] = j;   // thêm j ký tự\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n            else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}]},{label:"Ví dụ: Đếm đường đi tránh ô cấm",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"...\", \".#.\", \"...\"};\n    int R = 3, C = 3;\n    vector<vector<long long>> dp(R, vector<long long>(C, 0));\n    dp[0][0] = 1;\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++) {\n            if (g[i][j] == '#') { dp[i][j] = 0; continue; }\n            if (i > 0) dp[i][j] += dp[i - 1][j];   // từ trên xuống\n            if (j > 0) dp[i][j] += dp[i][j - 1];   // từ trái sang\n        }\n    cout << dp[R - 1][C - 1] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"dp",ptr:["i","j"]}]}];
