makeEx2(document.getElementById("ex-l23"),sim23,[{t:"Gen chung",d:"File GENCHUNG.INP gồm hai dòng, mỗi dòng một xâu chỉ gồm các chữ A, C, G, T (độ dài 1 … 2000). Ghi vào GENCHUNG.OUT độ dài dãy con chung dài nhất của hai xâu (dãy con: xóa đi một số ký tự, giữ thứ tự).",tests:[{in:"ACCCGAC\nCGCACA",out:"4"},{in:"A\nA",out:"1"},{in:"A\nC",out:"0"},{in:"ACGT\nACGT",out:"4"},{in:"GAAGTTGCCGTACTAAATTATGACAGCCGGGGATCTTCCCGCAAATAGGGAGGGTCGCAA\nTCGCATCTAATTACCACATAGATTCAAGTCTGCAACCGATCATGTCTACG",out:"32"},{in:"CCCACAAACCAAACAACCCACCAACAAACCACCCACCAAACCACCCCCCCCCACACCCCACACACACACCAACAACACACACAAACCCAAAAAAAACCCA\nAACAACAAAACCACCACCACCCACCCAAACCCAACCCACCACACCACCCACACACACACCCAACCCCAAACAACCACAAAACCCCCCCCAAAAAACCAAAACACCCAAAAAACAACACAC",out:"86"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"GENCHUNG.INP\", \"r\")) {\n        freopen(\"GENCHUNG.INP\", \"r\", stdin);\n        freopen(\"GENCHUNG.OUT\", \"w\", stdout);\n    }\n    string a, b;\n    cin >> a >> b;\n    // dp[i][j]: LCS của a[0..i-1] và b[0..j-1]\n    cout << 0 << \"\\n\";\n    return 0;\n}",file:"GENCHUNG",perf:{gen:n=>"ACGT".repeat(n>>2)+"\n"+"TGCA".repeat(n>>2),ns:[40,80,160],need:"n2",limit:n=>40*n*n+2000,why:"Bảng n × m, mỗi ô O(1)."}},{t:"Sửa chính tả",d:"File SUALOI.INP gồm hai dòng: từ gõ sai a và từ đúng b (chữ thường, độ dài 1 … 2000). Mỗi thao tác thêm, xóa hoặc thay một ký tự. Ghi vào SUALOI.OUT số thao tác ít nhất để biến a thành b.",tests:[{in:"sunday\nsaturday",out:"3"},{in:"a\na",out:"0"},{in:"a\nb",out:"1"},{in:"abc\nabcd",out:"1"},{in:"kitten\nsitting",out:"3"},{in:"aaaaabbababbbaaabaaaaabaaaabaaabbaabbaaabbbaaabaaaaabaabaabb\nabbbabbabbbaaaaabaabbabbabbabbbaabbabbbababaaaabbaabbaa",out:"19"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"SUALOI.INP\", \"r\")) {\n        freopen(\"SUALOI.INP\", \"r\", stdin);\n        freopen(\"SUALOI.OUT\", \"w\", stdout);\n    }\n    string a, b;\n    cin >> a >> b;\n    int n = a.size(), m = b.size();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));   // quên khởi tạo biên\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1];\n            else dp[i][j] = 1 + min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}",file:"SUALOI"},{t:"Robot trong kho",d:"File ROBOT.INP: dòng 1 là R, C (1 ≤ R, C ≤ 1000); R dòng sau mỗi dòng C ký tự, “.” là ô trống, “#” là ô có kệ hàng. Ô (1, 1) luôn trống. Robot đi từ ô (1, 1) tới ô (R, C), mỗi bước sang phải hoặc xuống dưới, không đi vào ô có kệ. Ghi vào ROBOT.OUT số đường đi, chia lấy dư cho 10⁹ + 7.",tests:[{in:"3 3\n...\n.#.\n...",out:"2"},{in:"1 1\n.",out:"1"},{in:"2 2\n.#\n#.",out:"0"},{in:"30 30\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................\n..............................",out:"289070178"},{in:"20 25\n...#.......#...####...#..\n..................#......\n..##..#......#...#..#...#\n......###.#...#..#....#..\n.####.##.....##.#...#...#\n........#...........#....\n..#...##.#..#..#.#.#...#.\n..#....#.##.........#....\n.#...........#.....##....\n.#........#.....#.....#..\n....###.#.#..#...........\n.#...#.#.#..#.....#..#...\n...#........#............\n....#.............#......\n......#.##..........##...\n.....##...#......#.#.##.#\n..#.....#..........#.....\n......#....#.####........\n.#..#...#...#.#..........\n..##.....#..........#..#.",out:"2391738"},{in:"40 40\n...........#.#........#.....#......#....\n.#..............#................##.....\n..#....................#...........#....\n...........#.............#..#.#.........\n...#.....#...............#..........##.#\n........#....#............#..#..........\n..........#................#............\n................##.#.........##.........\n#.#............#.#.#...........#........\n.....#....#...........#.#...............\n...............#...............#....#...\n.#.........#............................\n.#...........#.....#......#.##........#.\n..........##.....#......................\n............#..........................#\n..#................#......#.............\n.#..#......................#.......#....\n#.......#.....#.#.......................\n.#...................##..#..............\n.#......#.............#..#..#.......#...\n....................................#..#\n..#...#......##.............#.#.......#.\n............#....................#......\n....#.........#....................##...\n.......#.......#....#....#...#..#.......\n.........#......................#.......\n#.#...#.#...............#.....##......##\n...#.........##..........#..#..#.#....##\n................#..##......#.#........#.\n.........................#....#.........\n.....#..................................\n...#...#..#.........#...................\n.............#.#.#........##............\n......#........#........................\n........#......#..#.....................\n...............................#..#.#...\n..#..##....#..........................#.\n............#........#......#.......#...\n.....................#..........###.....\n......#.....#.........##.#...........#..",out:"883662495"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"ROBOT.INP\", \"r\")) {\n        freopen(\"ROBOT.INP\", \"r\", stdin);\n        freopen(\"ROBOT.OUT\", \"w\", stdout);\n    }\n    int R, C;\n    cin >> R >> C;\n    vector<string> g(R);\n    for (auto& s : g) cin >> s;\n    vector<vector<long long>> dp(R, vector<long long>(C, 0));\n    // dp[i][j] = số đường tới ô (i, j)\n    cout << 0 << \"\\n\";\n    return 0;\n}",file:"ROBOT"}]);

